const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const os = require('os');

// Demonstrates: I/O-bound favors concurrency, CPU-bound favors parallelism

if (isMainThread) {
  const CORES = os.cpus().length;
  console.log(`Available cores: ${CORES}`);

  // --- I/O-BOUND: concurrency with async (single thread handles many) ---
  async function simulateIO(id) {
    // In a real app: await fetch(...) or fs.promises.readFile(...)
    await new Promise(r => setTimeout(r, 50)); // simulate network latency
    return `IO task ${id} done`;
  }

  async function runIOBound() {
    const start = Date.now();
    // 10 tasks, ~50ms each, run concurrently — total ≈ 50ms, not 500ms
    const results = await Promise.all(
      Array.from({ length: 10 }, (_, i) => simulateIO(i))
    );
    console.log(`I/O-bound: ${results.length} tasks in ${Date.now() - start}ms`);
  }

  // --- CPU-BOUND: parallelism with workers (N cores × throughput) ---
  function runCPUBound() {
    const start = Date.now();
    const promises = Array.from({ length: CORES }, (_, i) =>
      new Promise((resolve, reject) => {
        const w = new Worker(__filename, { workerData: { chunk: i, total: CORES } });
        w.on('message', resolve);
        w.on('error', reject);
      })
    );
    Promise.all(promises).then(results => {
      console.log(`CPU-bound: ${results.length} workers in ${Date.now() - start}ms`);
    });
  }

  runIOBound().then(runCPUBound);
} else {
  // Worker: CPU-intensive work (sum large range)
  const { chunk, total } = workerData;
  const size = 2e7;
  const start = Math.floor((size / total) * chunk);
  const end = Math.floor((size / total) * (chunk + 1));
  let sum = 0;
  for (let i = start; i < end; i++) sum += i;
  parentPort.postMessage({ chunk, sum });
}

// Amdahl's Law modeled in JS
function amdahlSpeedup(parallelFraction, numCores) {
  // parallelFraction: 0.0 to 1.0 (portion that can be parallelized)
  const sequential = 1 - parallelFraction;
  return 1 / (sequential + parallelFraction / numCores);
}

// Example: 80% of work is parallelizable
const p = 0.8;
for (const cores of [1, 2, 4, 8, 16, 32, 64, Infinity]) {
  const s = amdahlSpeedup(p, cores);
  console.log(`Cores: ${cores === Infinity ? '∞' : cores.toString().padStart(2)}, Speedup: ${s.toFixed(2)}x`);
}
// Cores:  1, Speedup: 1.00x
// Cores:  2, Speedup: 1.67x
// Cores:  8, Speedup: 3.08x
// Cores: 64, Speedup: 4.71x
// Cores:  ∞, Speedup: 5.00x  ← hard ceiling at 1/(1-0.8)
